import java.util.*;
abstract class Customer {double amount;Customer(double a){amount=a;}abstract double calculate();abstract String getType();}
class Student extends Customer {Student(double a){super(a);}double calculate(){return amount*.90;}String getType(){return "STUDENT";}}
class Staff extends Customer {Staff(double a){super(a);}double calculate(){return amount*.95;}String getType(){return "STAFF";}}
class Guest extends Customer {Guest(double a){super(a);}double calculate(){return amount+10;}String getType(){return "GUEST";}}
public class CanteenBillingCounter {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();double total=0;for(int i=0;i<n;i++){String type=sc.next();double amount=sc.nextDouble();Customer c;switch(type){case "STUDENT":c=new Student(amount);break;case "STAFF":c=new Staff(amount);break;default:c=new Guest(amount);}double result=c.calculate();System.out.printf("%s: %.2f%n",c.getType(),result);total+=result;}System.out.printf("Total: %.2f%n",total);sc.close();}}